showModifiedLine(lineNumber, preference, tx) {
        const top = lineNumber + 1 - (this.modifiedLineNumber + this.d.get());
        const bottom = (this.modifiedLineNumber - this.g.get() + this.lineCount) - lineNumber;
        if (preference === 0 /* RevealPreference.FromCloserSide */ && top < bottom || preference === 1 /* RevealPreference.FromTop */) {
            this.d.set(this.d.get() + top, tx);
        }
        else {
            this.g.set(this.g.get() + bottom, tx);
        }
    }
